# ---------------------------------------------------------------------------
# Names, entities, character references
# ---------------------------------------------------------------------------

@st.composite
def xml_name(draw, lengths=None):
    if lengths is None:
        lengths = NAME_LENGTHS
    n = draw(st.sampled_from(lengths))
    if n <= 0:
        return ""
    first = draw(st.sampled_from(NAME_START_CHARS))
    if n == 1:
        return first
    rest = draw(st.text(alphabet=NAME_CHAR_POOL, min_size=n - 1, max_size=n - 1))
    return first + rest


@st.composite
def char_ref(draw):
    value = draw(st.sampled_from(CHARREF_VALUES))
    hexform = draw(st.booleans())
    if hexform:
        digits = format(value, "x")
        if draw(st.booleans()):
            digits = digits.upper()
        return "&#x" + digits + ";"
    return "&#" + str(value) + ";"


@st.composite
def entity_ref(draw):
    kind = draw(st.sampled_from(["named_ok", "named_unsupported", "length_sweep"]))
    if kind == "named_ok":
        name = draw(st.sampled_from(NAMED_ENTITIES_VALID))
    elif kind == "named_unsupported":
        name = draw(st.sampled_from(NAMED_ENTITIES_INVALID))
    else:
        n = draw(st.sampled_from(ENTITY_NAME_LENGTHS))
        first = draw(st.sampled_from(NAME_START_ASCII))
        if n <= 1:
            name = first
        else:
            rest = draw(st.text(alphabet=NAME_CHAR_POOL, min_size=n - 1, max_size=n - 1))
            name = first + rest
    return "&" + name + ";"


def reference():
    return st.one_of(char_ref(), entity_ref())


