@st.composite
def attr_value_plain(draw, quote, value_lengths=None):
    if value_lengths is None:
        value_lengths = ATTR_VALUE_LENGTHS_LIGHT
    n = draw(st.sampled_from(value_lengths))
    alphabet = SAFE_TEXT_CHARS.replace(quote, "")
    if not alphabet:
        alphabet = "x"
    base = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
    if n > 0 and draw(st.integers(min_value=0, max_value=4)) == 0:
        ref = draw(reference())
        mid = n // 2
        base = base[:mid] + ref + base[mid:]
    return base


@st.composite
def attribute(draw, used_names, value_lengths=None):
    if value_lengths is None:
        value_lengths = ATTR_VALUE_LENGTHS_LIGHT
    reuse = bool(used_names) and draw(st.integers(min_value=0, max_value=9)) == 0
    if reuse:
        name = draw(st.sampled_from(used_names))
    else:
        name = draw(xml_name())
    used_names.append(name)
    kind = draw(st.sampled_from(["dquot", "dquot", "dquot", "squot", "unquoted"]))
    if kind == "unquoted":
        n = draw(st.sampled_from([1, 2, 3, 4, 5, 8, 16, 32]))
        alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-"
        value = draw(st.text(alphabet=alphabet, min_size=n, max_size=n))
        if value == "":
            value = "1"
        return name + "=" + value
    quote = '"' if kind == "dquot" else "'"
    body = draw(attr_value_plain(quote, value_lengths))
    return name + "=" + quote + body + quote


@st.composite
def attributes(draw, count_choices=None, value_lengths=None):
    if count_choices is None:
        count_choices = ATTR_COUNTS_LIGHT
    if value_lengths is None:
        value_lengths = ATTR_VALUE_LENGTHS_LIGHT
    count = draw(st.sampled_from(count_choices))
    used = []
    parts = []
    for _ in range(count):
        parts.append(draw(attribute(used, value_lengths)))
    if not parts:
        return ""
    return " " + " ".join(parts)


# ---------------------------------------------------------------------------
# Organic recursive content: st.recursive self-bounds total structure size
# via max_leaves, and Hypothesis shrinks it normally. Each recursive step is
# an element built from ONE drawn name reused for both its open and close
# tag, so tags always match here.
# ---------------------------------------------------------------------------

def content_leaf():
    return st.one_of(
        chardata(),
        reference(),
        cdata_section(),
        pi_section(),
        comment_section(),
    )


def _build_element_node(name, attrs, kids):
    return "<" + name + attrs + ">" + "".join(kids) + "</" + name + ">"


def content_node():
    def extend(children):
        return st.builds(
            _build_element_node,
            xml_name(),
            attributes(),
            st.lists(children, min_size=0, max_size=6),
        )
    return st.recursive(content_leaf(), extend, max_leaves=25)


@st.composite
def root_element(draw):
    name = draw(xml_name())
    attrs = draw(attributes())
    self_close = draw(st.integers(min_value=0, max_value=9)) == 0
    if self_close:
        return "<" + name + attrs + "/>"
    kids = draw(st.lists(content_node(), min_size=0, max_size=8))
    return "<" + name + attrs + ">" + "".join(kids) + "</" + name + ">"


