@st.composite
def prolog(draw):
    attrs_str = draw(attributes())
    if attrs_str == "":
        space = draw(st.sampled_from(["", " "]))
    else:
        space = " "
    return "<?xml" + space + attrs_str + "?>"


@st.composite
def prolog_with_encoding_mismatch(draw):
    enc = draw(st.sampled_from(
        ["UTF-16", "ISO-8859-1", "UTF-32", "us-ascii", "utf-16le", "utf-16be", "Shift_JIS"]
    ))
    return '<?xml version="1.0" encoding="' + enc + '"?>'


@st.composite
def misc_item(draw):
    kind = draw(st.sampled_from(["comment", "pi", "ws"]))
    if kind == "comment":
        return draw(comment_section())
    if kind == "pi":
        return draw(pi_section())
    n = draw(st.sampled_from([1, 2, 3, 4, 8, 16]))
    ws_char = draw(st.sampled_from([" ", "\t", "\n"]))
    return ws_char * n


@st.composite
def well_formed_document(draw):
    parts = []
    if draw(st.booleans()):
        parts.append(draw(prolog()))
    lead_misc = draw(st.sampled_from([0, 0, 0, 1, 2, 3]))
    for _ in range(lead_misc):
        parts.append(draw(misc_item()))
    parts.append(draw(root_element()))
    trail_misc = draw(st.sampled_from([0, 0, 0, 1, 2]))
    for _ in range(trail_misc):
        parts.append(draw(misc_item()))
    return "".join(parts)


