# Byte-level hostility, expressed as a str via the surrogateescape
# convention: chr(0xDC00 + b) for a raw byte b in 0x80-0xFF round-trips back
# to that exact byte under `.encode('utf-8', 'surrogateescape')`. Bytes below
# 0x80 (e.g. NUL) are just their normal character.
# ---------------------------------------------------------------------------

def _raw_byte_char(b):
    if b < 0x80:
        return chr(b)
    return chr(0xDC00 + b)


def _raw_bytes_str(byte_values):
    return "".join(_raw_byte_char(b) for b in byte_values)


UTF8_BOM = _raw_bytes_str([0xEF, 0xBB, 0xBF])
