    quote = draw(st.sampled_from(['"', "'"]))
    alphabet = SAFE_TEXT_CHARS.replace(quote, "")
    prefix_len = n // 2
    prefix = draw(st.text(alphabet=alphabet, min_size=prefix_len, max_size=prefix_len))
    suffix = draw(st.text(alphabet=alphabet, min_size=n - prefix_len, max_size=n - prefix_len))
