# ---------------------------------------------------------------------------
# One-defect-deep-inside chain for exact nesting-depth boundaries, plus other
# counted-thing defects (unterminated markup, control chars, bad entities,
# extreme char refs). depth is drawn, so it varies and shrinks; only the
# *string repetition* is a plain loop, not hand-flattened grammar recursion.
# ---------------------------------------------------------------------------

@st.composite
def _maybe_defect_text(draw):
    trigger = draw(st.integers(min_value=0, max_value=4))
    if trigger != 0:
        return None
    kind = draw(st.sampled_from([
        "utf8_bom", "utf16_bom_odd", "truncated2", "truncated3", "truncated4",
        "lone_cont", "overlong2", "overlong4", "invalid_lead_fe",
        "embedded_nul", "unterminated_comment", "unterminated_cdata",
        "control_char", "unsupported_entity", "entity_toolong", "charref_extreme",
    ]))
    if kind == "utf8_bom":
        return UTF8_BOM
    if kind == "utf16_bom_odd":
        return UTF16_LE_BOM_ODD
    if kind == "truncated2":
        return TRUNCATED_2BYTE
    if kind == "truncated3":
        return TRUNCATED_3BYTE
    if kind == "truncated4":
        return TRUNCATED_4BYTE
    if kind == "lone_cont":
        return LONE_CONTINUATION
    if kind == "overlong2":
        return OVERLONG_SLASH
    if kind == "overlong4":
        return OVERLONG_4BYTE_NUL
    if kind == "invalid_lead_fe":
        return INVALID_LEAD_FE
    if kind == "embedded_nul":
        return "value" + EMBEDDED_NUL + "tail"
    if kind == "unterminated_comment":
        return "<!-- never closed"
    if kind == "unterminated_cdata":
        return "<![CDATA[ never closed"
    if kind == "control_char":
        c = draw(st.sampled_from(CONTROL_CHARS))
        return "before" + c + "after"
    if kind == "unsupported_entity":
        name = draw(st.sampled_from(NAMED_ENTITIES_INVALID))
        return "&" + name + ";"
    if kind == "entity_toolong":
        n = draw(st.sampled_from([200, 256, 300, 400]))
        name = draw(st.text(alphabet=NAME_START_ASCII, min_size=n, max_size=n))
        return "&" + name + ";"
    n_val = draw(st.sampled_from(CHARREF_VALUES))
    return "&#" + str(n_val) + ";"


@st.composite
def deep_chain(draw):
    depth = draw(st.sampled_from(NESTING_DEPTHS))
    if depth > 300:
        name = draw(xml_name([1, 2, 3]))
    else:
        name = draw(xml_name(NAME_LENGTHS[:25]))
    leaf = draw(chardata())
    defect = draw(_maybe_defect_text())
    core = defect if defect is not None else leaf
    levels = depth + 1
    open_tag = "<" + name + ">"
    close_tag = "</" + name + ">"
    return (open_tag * levels) + core + (close_tag * levels)


@st.composite
def deep_boundary_document(draw):
    parts = []
    if draw(st.booleans()):
        parts.append(draw(prolog()))
    parts.append(draw(deep_chain()))
    return "".join(parts)


